-- ============================================================
--  177_experiencias_alimentos_quiz.sql
--
--  Curso de Manipulación de Alimentos: las quince experiencias se
--  regeneran con el quiz, la actividad y el foro que ya existían en las
--  migraciones 161 y 162. Antes se habían generado sin ese material y
--  el caso era genérico. No agrega clases ni toca videos.
-- ============================================================

DO $alim$
DECLARE
  v_curso BIGINT;
BEGIN
  SELECT id INTO v_curso FROM aula_courses WHERE kind = 'edvanta' AND title = 'Curso de Manipulación de Alimentos' AND deleted_at IS NULL LIMIT 1;
  IF v_curso IS NULL THEN RAISE NOTICE 'Alimentos: no existe el curso.'; RETURN; END IF;
  UPDATE aula_lesson_blocks SET data = $j${"v":1,"duracion":25,"gancho":{"titulo":"Qué es la inocuidad y por qué un alimento enferma","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, el área de preparación está limpia, pero el manipulador no se lavó las manos. Lo que está en juego es el criterio de qué es la inocuidad y por qué un alimento enferma. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar qué es la inocuidad y por qué un alimento enferma con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar qué es la inocuidad y por qué un alimento enferma con unidad 1. Inocuidad y lo que exige la norma y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar qué es la inocuidad y por qué un alimento enferma y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Un alimento es inocuo cuando no causa daño a quien lo consume, siempre que se prepare y se coma según su uso previsto. La inocuidad no se ve: un plato puede verse, oler y saber bien y aun así estar contaminado. Por eso la manipulación de alimentos se apoya en prácticas que se cumplen siempre, no en la apariencia. Enfermedades transmitidas por alimentos (ETA) Una ETA es la enfermedad que aparece por comer un alimento o beber agua contaminados. Según la OMS, en la mayoría de los casos los síntomas aparecen entre 24 y 72 horas después de comer,…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, qué es la inocuidad y por qué un alimento enferma aparece en medio de una decisión que no admite improvisación: el área de preparación está limpia, pero el manipulador no se lavó las manos. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Inocuidad y lo que exige la norma. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Un alimento es inocuo cuando no causa daño a quien lo consume, siempre que se prepare y se coma según su uso previsto. La inocuidad no se ve: un plato puede verse, oler y saber bien y aun así estar contaminado. Por eso la manipulación de alimentos se apoya en prácticas que se cumplen siempre, no en la apariencia. Enfermedades transmitidas por alimentos (ETA) Una ETA es la enfermedad que aparece por comer un alimento o beber agua contaminados. Según la OMS, en la mayoría de los casos los síntomas aparecen entre 24 y 72 horas después de comer,…","Una pregunta que se usa para comprobar esta clase es: «Un alimento es inocuo cuando:» La respuesta correcta se apoya en lo siguiente: La inocuidad es que el alimento no cause daño; no se reconoce por su aspecto. La fuente citada es: Resolución 2674 de 2013 y manual de la OMS sobre las cinco claves de la inocuidad.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Inocuidad y lo que exige la norma y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Una tabla con cada peligro, dónde lo viste, cómo llegaría al alimento y una medida para controlarlo según la Resolución 2674 de 2013.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar qué es la inocuidad y por qué un alimento enferma, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y anota qué alimento, superficie o práctica está involucrada. Evidencia que debe quedar: Registro del paso.","Identifica el peligro y la causa probable. Evidencia que debe quedar: Registro del paso.","Define la medida de control y la evidencia que debes dejar. Evidencia que debe quedar: Registro del paso.","Revisa la fuente y escribe la conclusión. Evidencia que debe quedar: Registro del paso.","La respuesta esperada de la unidad ayuda a calibrar el nivel: Aplica la Resolución 2674 de 2013 y las cinco claves de la OMS: separa, cocina, enfría, limpia y usa agua segura. Úsala como espejo, no como texto para copiar: compara tu razonamiento con ella y detecta qué te faltó."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: guardar crudos junto a listos para consumo Corrección: la separación evita que los jugos contaminen alimentos que no volverán a cocinarse.","Error: no documentar la limpieza Corrección: sin registro no se puede demostrar que la limpieza se hizo y se verificó.","Error: lavar la carne cruda en el fregadero Corrección: las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar qué es la inocuidad y por qué un alimento enferma en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Qué es la inocuidad y por qué un alimento enferma»?","respuesta":"Un alimento es inocuo cuando no causa daño a quien lo consume, siempre que se prepare y se coma según su uso previsto. La inocuidad no se ve: un plato puede verse, oler y saber bien y aun así estar contaminado. Por eso la manipulación de alimentos se apoya en prácticas que se cumplen siempre, no en la apariencia. Enfermedades transmitidas por alimentos (ETA) Una ETA es la enfermedad que aparece por comer un alimento o beber agua contaminados. Según la OMS, en la mayoría de los casos los síntomas aparecen entre 24 y 72 horas después de comer,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Una tabla con cada peligro, dónde lo viste, cómo llegaría al alimento y una medida para controlarlo según la Resolución 2674 de 2013.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Qué es la inocuidad y por qué un alimento enferma se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Inocuidad y lo que exige la norma.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente qué es la inocuidad y por qué un alimento enferma en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de qué es la inocuidad y por qué un alimento enferma"}],"keywords":["curso","manipulación","alimentos","inocuidad","alimento","enferma","unidad","exige","norma"],"mapa":{"centro":"Qué es la inocuidad y por qué un alimento enferma","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 1. Inocuidad y lo que exige la norma","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se aplica: Mi diagnóstico de riesgos","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y anota qué alimento, superficie o práctica está involucrada.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Identifica el peligro y la causa probable.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define la medida de control y la evidencia que debes dejar.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Revisa la fuente y escribe la conclusión.","icono":"FileCheck","evidencia":"Registro del paso"}]},"caso":{"titulo":"Qué es la inocuidad y por qué un alimento enferma","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, el equipo analiza este caso de unidad 1. Inocuidad y lo que exige la norma: Observa tu puesto de trabajo (o un establecimiento de alimentos que conozcas) durante un turno e identifica un peligro biológico, uno químico y uno físico. Entregable: Una tabla con cada peligro, dónde lo viste, cómo llegaría al alimento y una medida para controlarlo según la Resolución 2674 de 2013. La pregunta que decide esta clase es: Un alimento es inocuo cuando:","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"No causa daño a quien lo consume","correcta":true,"retro":"La inocuidad es que el alimento no cause daño; no se reconoce por su aspecto."},{"texto":"Se ve, huele y sabe bien al servirlo","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"Está recién preparado en la cocina","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"No contiene ningún tipo de conservante","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."}]}}$j$::jsonb, updated_at = NOW()
   WHERE lesson_id = 1700 AND type = 'experiencia' AND deleted_at IS NULL;
  UPDATE aula_lesson_blocks SET data = $j${"v":1,"duracion":25,"gancho":{"titulo":"La Resolución 2674 de 2013: obligaciones del manipulador y de la empresa","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, un proveedor entrega un alimento a una temperatura fuera de rango. Lo que está en juego es el criterio de la Resolución 2674 de 2013: obligaciones del manipulador y de la empresa. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar la Resolución 2674 de 2013: obligaciones del manipulador y de la empresa con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar la Resolución 2674 de 2013: obligaciones del manipulador y de la empresa con unidad 1. Inocuidad y lo que exige la norma y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar la Resolución 2674 de 2013: obligaciones del manipulador y de la empresa y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"La Resolución 2674 de 2013 del Ministerio de Salud y Protección Social establece los requisitos sanitarios para quienes fabrican, procesan, preparan, envasan, almacenan, transportan, distribuyen y comercializan alimentos en Colombia. Para el manipulador, los artículos más importantes son el 11, el 12, el 13 y el 14. Artículo 11: estado de salud Exige un certificado médico de aptitud para manipular alimentos, con examen al menos una vez al año, y examen adicional cuando haya razones clínicas o epidemiológicas. Lo verás a fondo en la clase 1.3.…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, la Resolución 2674 de 2013: obligaciones del manipulador y de la empresa aparece en medio de una decisión que no admite improvisación: un proveedor entrega un alimento a una temperatura fuera de rango. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Inocuidad y lo que exige la norma. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: La Resolución 2674 de 2013 del Ministerio de Salud y Protección Social establece los requisitos sanitarios para quienes fabrican, procesan, preparan, envasan, almacenan, transportan, distribuyen y comercializan alimentos en Colombia. Para el manipulador, los artículos más importantes son el 11, el 12, el 13 y el 14. Artículo 11: estado de salud Exige un certificado médico de aptitud para manipular alimentos, con examen al menos una vez al año, y examen adicional cuando haya razones clínicas o epidemiológicas. Lo verás a fondo en la clase 1.3.…","Una pregunta que se usa para comprobar esta clase es: «Según la OMS, en la mayoría de las ETA los síntomas aparecen:» La respuesta correcta se apoya en lo siguiente: El manual de la OMS indica que en la mayoría de los casos aparecen entre 24 y 72 horas después. La fuente citada es: Resolución 2674 de 2013 y manual de la OMS sobre las cinco claves de la inocuidad.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Inocuidad y lo que exige la norma y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Una tabla con cada peligro, dónde lo viste, cómo llegaría al alimento y una medida para controlarlo según la Resolución 2674 de 2013.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar la Resolución 2674 de 2013: obligaciones del manipulador y de la empresa, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y anota qué alimento, superficie o práctica está involucrada. Evidencia que debe quedar: Registro del paso.","Identifica el peligro y la causa probable. Evidencia que debe quedar: Registro del paso.","Define la medida de control y la evidencia que debes dejar. Evidencia que debe quedar: Registro del paso.","Revisa la fuente y escribe la conclusión. Evidencia que debe quedar: Registro del paso.","La respuesta esperada de la unidad ayuda a calibrar el nivel: Aplica la Resolución 2674 de 2013 y las cinco claves de la OMS: separa, cocina, enfría, limpia y usa agua segura. Úsala como espejo, no como texto para copiar: compara tu razonamiento con ella y detecta qué te faltó.","La discusión de la unidad añade otra capa: Comparte un peligro que hayas visto y la medida que propones. Responde a dos compañeros con una sugerencia concreta. Comparte un peligro que hayas visto y la medida que propones. Responde a dos compañeros con una sugerencia concreta. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: no documentar la limpieza Corrección: sin registro no se puede demostrar que la limpieza se hizo y se verificó.","Error: confiar en el olor o el color Corrección: los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento.","Error: lavar la carne cruda en el fregadero Corrección: las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar la Resolución 2674 de 2013: obligaciones del manipulador y de la empresa en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «La Resolución 2674 de 2013: obligaciones del manipulador y de la empresa»?","respuesta":"La Resolución 2674 de 2013 del Ministerio de Salud y Protección Social establece los requisitos sanitarios para quienes fabrican, procesan, preparan, envasan, almacenan, transportan, distribuyen y comercializan alimentos en Colombia. Para el manipulador, los artículos más importantes son el 11, el 12, el 13 y el 14. Artículo 11: estado de salud Exige un certificado médico de aptitud para manipular alimentos, con examen al menos una vez al año, y examen adicional cuando haya razones clínicas o epidemiológicas. Lo verás a fondo en la clase 1.3.…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Una tabla con cada peligro, dónde lo viste, cómo llegaría al alimento y una medida para controlarlo según la Resolución 2674 de 2013.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["La Resolución 2674 de 2013: obligaciones del manipulador y de la empresa se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Inocuidad y lo que exige la norma.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente la Resolución 2674 de 2013: obligaciones del manipulador y de la empresa en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de la Resolución 2674 de 2013: obligaciones del manipulador y de la empresa"}],"keywords":["curso","manipulación","alimentos","resolución","obligaciones","manipulador","empresa","unidad","inocuidad","exige","norma"],"mapa":{"centro":"La Resolución 2674 de 2013: obligaciones del manipulador y de la empresa","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 1. Inocuidad y lo que exige la norma","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se aplica: Mi diagnóstico de riesgos","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y anota qué alimento, superficie o práctica está involucrada.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Identifica el peligro y la causa probable.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define la medida de control y la evidencia que debes dejar.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Revisa la fuente y escribe la conclusión.","icono":"FileCheck","evidencia":"Registro del paso"}]},"caso":{"titulo":"La Resolución 2674 de 2013: obligaciones del manipulador y de la empresa","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, el equipo analiza este caso de unidad 1. Inocuidad y lo que exige la norma: Observa tu puesto de trabajo (o un establecimiento de alimentos que conozcas) durante un turno e identifica un peligro biológico, uno químico y uno físico. Entregable: Una tabla con cada peligro, dónde lo viste, cómo llegaría al alimento y una medida para controlarlo según la Resolución 2674 de 2013. La pregunta que decide esta clase es: Según la OMS, en la mayoría de las ETA los síntomas aparecen:","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"En los primeros 5 minutos tras comer","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"Entre 24 y 72 horas después de comer","correcta":true,"retro":"El manual de la OMS indica que en la mayoría de los casos aparecen entre 24 y 72 horas después."},{"texto":"Solo después de una semana de comer","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"Únicamente si el alimento huele mal","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."}]}}$j$::jsonb, updated_at = NOW()
   WHERE lesson_id = 1701 AND type = 'experiencia' AND deleted_at IS NULL;
  UPDATE aula_lesson_blocks SET data = $j${"v":1,"duracion":25,"gancho":{"titulo":"Estado de salud del manipulador","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, la nevera se dañó durante la noche y nadie registró la temperatura. Lo que está en juego es el criterio de estado de salud del manipulador. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar estado de salud del manipulador con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar estado de salud del manipulador con unidad 1. Inocuidad y lo que exige la norma y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar estado de salud del manipulador y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Una persona enferma puede contaminar los alimentos aunque no tenga síntomas graves. Por eso el artículo 11 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social pone el estado de salud como primera condición para manipular alimentos. Lo que exige el artículo 11 Certificado médico de aptitud: debe indicar si la persona es apta o no para manipular alimentos. La empresa organiza el examen al menos una vez al año . Examen adicional: cuando haya razones clínicas o epidemiológicas,…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, estado de salud del manipulador aparece en medio de una decisión que no admite improvisación: la nevera se dañó durante la noche y nadie registró la temperatura. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Inocuidad y lo que exige la norma. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Una persona enferma puede contaminar los alimentos aunque no tenga síntomas graves. Por eso el artículo 11 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social pone el estado de salud como primera condición para manipular alimentos. Lo que exige el artículo 11 Certificado médico de aptitud: debe indicar si la persona es apta o no para manipular alimentos. La empresa organiza el examen al menos una vez al año . Examen adicional: cuando haya razones clínicas o epidemiológicas,…","Una pregunta que se usa para comprobar esta clase es: «¿Cuántas horas de capacitación al año pide el plan del artículo 12 de la Resolución 2674 de 2013?» La respuesta correcta se apoya en lo siguiente: El artículo 12 pide un plan continuo de al menos 10 horas al año. La fuente citada es: Resolución 2674 de 2013 y manual de la OMS sobre las cinco claves de la inocuidad.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Inocuidad y lo que exige la norma y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Una tabla con cada peligro, dónde lo viste, cómo llegaría al alimento y una medida para controlarlo según la Resolución 2674 de 2013.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar estado de salud del manipulador, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y anota qué alimento, superficie o práctica está involucrada. Evidencia que debe quedar: Registro del paso.","Identifica el peligro y la causa probable. Evidencia que debe quedar: Registro del paso.","Define la medida de control y la evidencia que debes dejar. Evidencia que debe quedar: Registro del paso.","Revisa la fuente y escribe la conclusión. Evidencia que debe quedar: Registro del paso.","La respuesta esperada de la unidad ayuda a calibrar el nivel: Aplica la Resolución 2674 de 2013 y las cinco claves de la OMS: separa, cocina, enfría, limpia y usa agua segura. Úsala como espejo, no como texto para copiar: compara tu razonamiento con ella y detecta qué te faltó.","La discusión de la unidad añade otra capa: Comparte un peligro que hayas visto y la medida que propones. Responde a dos compañeros con una sugerencia concreta. Comparte un peligro que hayas visto y la medida que propones. Responde a dos compañeros con una sugerencia concreta. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: no documentar la limpieza Corrección: sin registro no se puede demostrar que la limpieza se hizo y se verificó.","Error: guardar crudos junto a listos para consumo Corrección: la separación evita que los jugos contaminen alimentos que no volverán a cocinarse.","Error: confiar en el olor o el color Corrección: los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar estado de salud del manipulador en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Estado de salud del manipulador»?","respuesta":"Una persona enferma puede contaminar los alimentos aunque no tenga síntomas graves. Por eso el artículo 11 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social pone el estado de salud como primera condición para manipular alimentos. Lo que exige el artículo 11 Certificado médico de aptitud: debe indicar si la persona es apta o no para manipular alimentos. La empresa organiza el examen al menos una vez al año . Examen adicional: cuando haya razones clínicas o epidemiológicas,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Una tabla con cada peligro, dónde lo viste, cómo llegaría al alimento y una medida para controlarlo según la Resolución 2674 de 2013.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Estado de salud del manipulador se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Inocuidad y lo que exige la norma.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente estado de salud del manipulador en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de estado de salud del manipulador"}],"keywords":["curso","manipulación","alimentos","estado","salud","manipulador","unidad","inocuidad","exige","norma"],"mapa":{"centro":"Estado de salud del manipulador","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 1. Inocuidad y lo que exige la norma","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se aplica: Mi diagnóstico de riesgos","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y anota qué alimento, superficie o práctica está involucrada.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Identifica el peligro y la causa probable.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define la medida de control y la evidencia que debes dejar.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Revisa la fuente y escribe la conclusión.","icono":"FileCheck","evidencia":"Registro del paso"}]},"caso":{"titulo":"Estado de salud del manipulador","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, el equipo analiza este caso de unidad 1. Inocuidad y lo que exige la norma: Observa tu puesto de trabajo (o un establecimiento de alimentos que conozcas) durante un turno e identifica un peligro biológico, uno químico y uno físico. Entregable: Una tabla con cada peligro, dónde lo viste, cómo llegaría al alimento y una medida para controlarlo según la Resolución 2674 de 2013. La pregunta que decide esta clase es: ¿Cuántas horas de capacitación al año pide el plan del artículo 12 de la Resolución 2674 de 2013?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Al menos 2 horas","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"Al menos 5 horas","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"Al menos 10 horas","correcta":true,"retro":"El artículo 12 pide un plan continuo de al menos 10 horas al año."},{"texto":"Al menos 40 horas","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."}]}}$j$::jsonb, updated_at = NOW()
   WHERE lesson_id = 1702 AND type = 'experiencia' AND deleted_at IS NULL;
  UPDATE aula_lesson_blocks SET data = $j${"v":1,"duracion":25,"gancho":{"titulo":"Lavado de manos: cuándo y cómo","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, el área de preparación está limpia, pero el manipulador no se lavó las manos. Lo que está en juego es el criterio de lavado de manos: cuándo y cómo. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar lavado de manos: cuándo y cómo con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar lavado de manos: cuándo y cómo con unidad 2. Higiene personal y prácticas higiénicas y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar lavado de manos: cuándo y cómo y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Las manos son el vehículo más frecuente de contaminación. La OMS recuerda que los microorganismos peligrosos están en el suelo, el agua, los animales y las personas, y que el menor contacto puede transferirlos a los alimentos. Cuándo lavarte las manos El numeral 4 del artículo 14 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social exige lavarse las manos con agua y jabón desinfectante al iniciar labores , cada vez que salgas y regreses al área y después de manipular cualquier material que pueda contaminar .…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, lavado de manos: cuándo y cómo aparece en medio de una decisión que no admite improvisación: el área de preparación está limpia, pero el manipulador no se lavó las manos. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Higiene personal y prácticas higiénicas. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Las manos son el vehículo más frecuente de contaminación. La OMS recuerda que los microorganismos peligrosos están en el suelo, el agua, los animales y las personas, y que el menor contacto puede transferirlos a los alimentos. Cuándo lavarte las manos El numeral 4 del artículo 14 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social exige lavarse las manos con agua y jabón desinfectante al iniciar labores , cada vez que salgas y regreses al área y después de manipular cualquier material que pueda contaminar .…","Una pregunta que se usa para comprobar esta clase es: «¿Durante cuánto tiempo, como mínimo, debes enjabonarte las manos según la OMS?» La respuesta correcta se apoya en lo siguiente: La OMS indica enjabonarse durante al menos 20 segundos. La fuente citada es: Resolución 2674 de 2013 y manual de la OMS sobre las cinco claves de la inocuidad.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 2. Higiene personal y prácticas higiénicas y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «La lista diligenciada, los incumplimientos que encontraste y cómo los corregiste.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar lavado de manos: cuándo y cómo, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y anota qué alimento, superficie o práctica está involucrada. Evidencia que debe quedar: Registro del paso.","Identifica el peligro y la causa probable. Evidencia que debe quedar: Registro del paso.","Define la medida de control y la evidencia que debes dejar. Evidencia que debe quedar: Registro del paso.","Revisa la fuente y escribe la conclusión. Evidencia que debe quedar: Registro del paso.","La respuesta esperada de la unidad ayuda a calibrar el nivel: Aplica la Resolución 2674 de 2013 y las cinco claves de la OMS: separa, cocina, enfría, limpia y usa agua segura. Úsala como espejo, no como texto para copiar: compara tu razonamiento con ella y detecta qué te faltó."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confiar en el olor o el color Corrección: los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento.","Error: romper la cadena de frío Corrección: una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano.","Error: guardar crudos junto a listos para consumo Corrección: la separación evita que los jugos contaminen alimentos que no volverán a cocinarse.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar lavado de manos: cuándo y cómo en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Lavado de manos: cuándo y cómo»?","respuesta":"Las manos son el vehículo más frecuente de contaminación. La OMS recuerda que los microorganismos peligrosos están en el suelo, el agua, los animales y las personas, y que el menor contacto puede transferirlos a los alimentos. Cuándo lavarte las manos El numeral 4 del artículo 14 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social exige lavarse las manos con agua y jabón desinfectante al iniciar labores , cada vez que salgas y regreses al área y después de manipular cualquier material que pueda contaminar .…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: La lista diligenciada, los incumplimientos que encontraste y cómo los corregiste.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Lavado de manos: cuándo y cómo se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Higiene personal y prácticas higiénicas.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente lavado de manos: cuándo y cómo en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de lavado de manos: cuándo y cómo"}],"keywords":["curso","manipulación","alimentos","lavado","manos","cuándo","unidad","higiene","personal","prácticas","higiénicas"],"mapa":{"centro":"Lavado de manos: cuándo y cómo","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 2. Higiene personal y prácticas higiénicas","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se aplica: Lista de chequeo de prácticas higiénicas","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y anota qué alimento, superficie o práctica está involucrada.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Identifica el peligro y la causa probable.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define la medida de control y la evidencia que debes dejar.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Revisa la fuente y escribe la conclusión.","icono":"FileCheck","evidencia":"Registro del paso"}]},"caso":{"titulo":"Lavado de manos: cuándo y cómo","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, el equipo analiza este caso de unidad 2. Higiene personal y prácticas higiénicas: Arma una lista de chequeo con los numerales del artículo 14 de la Resolución 2674 de 2013 y aplícala a ti mismo durante tres turnos. Entregable: La lista diligenciada, los incumplimientos que encontraste y cómo los corregiste. La pregunta que decide esta clase es: ¿Durante cuánto tiempo, como mínimo, debes enjabonarte las manos según la OMS?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"5 segundos","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"10 segundos","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"15 segundos","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"20 segundos","correcta":true,"retro":"La OMS indica enjabonarse durante al menos 20 segundos."}]}}$j$::jsonb, updated_at = NOW()
   WHERE lesson_id = 1703 AND type = 'experiencia' AND deleted_at IS NULL;
  UPDATE aula_lesson_blocks SET data = $j${"v":1,"duracion":25,"gancho":{"titulo":"Dotación y presentación personal","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, un cliente reporta un posible malestar después de consumir un producto. Lo que está en juego es el criterio de dotación y presentación personal. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar dotación y presentación personal con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar dotación y presentación personal con unidad 2. Higiene personal y prácticas higiénicas y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar dotación y presentación personal y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"La dotación protege el alimento de ti, no a ti del alimento. Por eso la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social es tan precisa sobre cómo debe ser. Vestimenta de trabajo (numerales 2 y 3) De color claro, para que se vea la suciedad; no se permiten grises ni tonos que la oculten. Con cierres o broches en lugar de botones, que pueden caer al alimento. Sin bolsillos por encima de la cintura. Con delantal bien atado. La empresa debe entregarla en cantidad suficiente.…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, dotación y presentación personal aparece en medio de una decisión que no admite improvisación: un cliente reporta un posible malestar después de consumir un producto. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Higiene personal y prácticas higiénicas. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: La dotación protege el alimento de ti, no a ti del alimento. Por eso la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social es tan precisa sobre cómo debe ser. Vestimenta de trabajo (numerales 2 y 3) De color claro, para que se vea la suciedad; no se permiten grises ni tonos que la oculten. Con cierres o broches en lugar de botones, que pueden caer al alimento. Sin bolsillos por encima de la cintura. Con delantal bien atado. La empresa debe entregarla en cantidad suficiente.…","Una pregunta que se usa para comprobar esta clase es: «¿De qué color debe ser la ropa de trabajo según la Resolución 2674 de 2013?» La respuesta correcta se apoya en lo siguiente: El numeral 2 del artículo 14 pide ropa de color claro; no se permiten grises ni tonos que oculten la suciedad. La fuente citada es: Resolución 2674 de 2013 y manual de la OMS sobre las cinco claves de la inocuidad.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 2. Higiene personal y prácticas higiénicas y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «La lista diligenciada, los incumplimientos que encontraste y cómo los corregiste.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar dotación y presentación personal, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y anota qué alimento, superficie o práctica está involucrada. Evidencia que debe quedar: Registro del paso.","Identifica el peligro y la causa probable. Evidencia que debe quedar: Registro del paso.","Define la medida de control y la evidencia que debes dejar. Evidencia que debe quedar: Registro del paso.","Revisa la fuente y escribe la conclusión. Evidencia que debe quedar: Registro del paso.","La respuesta esperada de la unidad ayuda a calibrar el nivel: Aplica la Resolución 2674 de 2013 y las cinco claves de la OMS: separa, cocina, enfría, limpia y usa agua segura. Úsala como espejo, no como texto para copiar: compara tu razonamiento con ella y detecta qué te faltó."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: lavar la carne cruda en el fregadero Corrección: las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada.","Error: guardar crudos junto a listos para consumo Corrección: la separación evita que los jugos contaminen alimentos que no volverán a cocinarse.","Error: romper la cadena de frío Corrección: una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar dotación y presentación personal en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Dotación y presentación personal»?","respuesta":"La dotación protege el alimento de ti, no a ti del alimento. Por eso la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social es tan precisa sobre cómo debe ser. Vestimenta de trabajo (numerales 2 y 3) De color claro, para que se vea la suciedad; no se permiten grises ni tonos que la oculten. Con cierres o broches en lugar de botones, que pueden caer al alimento. Sin bolsillos por encima de la cintura. Con delantal bien atado. La empresa debe entregarla en cantidad suficiente.…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: La lista diligenciada, los incumplimientos que encontraste y cómo los corregiste.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Dotación y presentación personal se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Higiene personal y prácticas higiénicas.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente dotación y presentación personal en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de dotación y presentación personal"}],"keywords":["curso","manipulación","alimentos","dotación","presentación","personal","unidad","higiene","prácticas","higiénicas"],"mapa":{"centro":"Dotación y presentación personal","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 2. Higiene personal y prácticas higiénicas","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se aplica: Lista de chequeo de prácticas higiénicas","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y anota qué alimento, superficie o práctica está involucrada.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Identifica el peligro y la causa probable.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define la medida de control y la evidencia que debes dejar.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Revisa la fuente y escribe la conclusión.","icono":"FileCheck","evidencia":"Registro del paso"}]},"caso":{"titulo":"Dotación y presentación personal","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, el equipo analiza este caso de unidad 2. Higiene personal y prácticas higiénicas: Arma una lista de chequeo con los numerales del artículo 14 de la Resolución 2674 de 2013 y aplícala a ti mismo durante tres turnos. Entregable: La lista diligenciada, los incumplimientos que encontraste y cómo los corregiste. La pregunta que decide esta clase es: ¿De qué color debe ser la ropa de trabajo según la Resolución 2674 de 2013?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Oscuro, para disimular manchas","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"Gris, por ser un tono neutro","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"Claro, para que se vea la suciedad","correcta":true,"retro":"El numeral 2 del artículo 14 pide ropa de color claro; no se permiten grises ni tonos que oculten la suciedad."},{"texto":"Cualquiera, si está limpia","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."}]}}$j$::jsonb, updated_at = NOW()
   WHERE lesson_id = 1704 AND type = 'experiencia' AND deleted_at IS NULL;
  UPDATE aula_lesson_blocks SET data = $j${"v":1,"duracion":25,"gancho":{"titulo":"Guantes, tapabocas y comportamientos prohibidos","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, un proveedor entrega un alimento a una temperatura fuera de rango. Lo que está en juego es el criterio de guantes, tapabocas y comportamientos prohibidos. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar guantes, tapabocas y comportamientos prohibidos con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar guantes, tapabocas y comportamientos prohibidos con unidad 2. Higiene personal y prácticas higiénicas y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar guantes, tapabocas y comportamientos prohibidos y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Los elementos de protección ayudan, pero solo si se usan bien. La Resolución 2674 de 2013 del Ministerio de Salud y Protección Social lo deja claro en el artículo 14. Guantes (numeral 10) Si se usan, deben estar limpios y sin roturas, y recibir el mismo cuidado que las manos. Usar guantes no reemplaza el lavado de manos. Un guante que tocó dinero, el celular o carne cruda contamina igual que una mano sucia: se cambia. Tapabocas (numeral 6) Se usa tapabocas desechable cuando el riesgo lo exija,…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, guantes, tapabocas y comportamientos prohibidos aparece en medio de una decisión que no admite improvisación: un proveedor entrega un alimento a una temperatura fuera de rango. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Higiene personal y prácticas higiénicas. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Los elementos de protección ayudan, pero solo si se usan bien. La Resolución 2674 de 2013 del Ministerio de Salud y Protección Social lo deja claro en el artículo 14. Guantes (numeral 10) Si se usan, deben estar limpios y sin roturas, y recibir el mismo cuidado que las manos. Usar guantes no reemplaza el lavado de manos. Un guante que tocó dinero, el celular o carne cruda contamina igual que una mano sucia: se cambia. Tapabocas (numeral 6) Se usa tapabocas desechable cuando el riesgo lo exija,…","Una pregunta que se usa para comprobar esta clase es: «Usar guantes:» La respuesta correcta se apoya en lo siguiente: El numeral 10 aclara que los guantes no reemplazan el lavado de manos. La fuente citada es: Resolución 2674 de 2013 y manual de la OMS sobre las cinco claves de la inocuidad.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 2. Higiene personal y prácticas higiénicas y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «La lista diligenciada, los incumplimientos que encontraste y cómo los corregiste.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar guantes, tapabocas y comportamientos prohibidos, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y anota qué alimento, superficie o práctica está involucrada. Evidencia que debe quedar: Registro del paso.","Identifica el peligro y la causa probable. Evidencia que debe quedar: Registro del paso.","Define la medida de control y la evidencia que debes dejar. Evidencia que debe quedar: Registro del paso.","Revisa la fuente y escribe la conclusión. Evidencia que debe quedar: Registro del paso.","La respuesta esperada de la unidad ayuda a calibrar el nivel: Aplica la Resolución 2674 de 2013 y las cinco claves de la OMS: separa, cocina, enfría, limpia y usa agua segura. Úsala como espejo, no como texto para copiar: compara tu razonamiento con ella y detecta qué te faltó.","La discusión de la unidad añade otra capa: ¿Cuál práctica del artículo 14 cuesta más cumplir en tu trabajo y por qué? Propón una solución práctica y comenta la de dos compañeros. ¿Cuál práctica del artículo 14 cuesta más cumplir en tu trabajo y por qué? Propón una solución práctica y comenta la de dos compañeros. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: romper la cadena de frío Corrección: una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano.","Error: guardar crudos junto a listos para consumo Corrección: la separación evita que los jugos contaminen alimentos que no volverán a cocinarse.","Error: confiar en el olor o el color Corrección: los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar guantes, tapabocas y comportamientos prohibidos en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Guantes, tapabocas y comportamientos prohibidos»?","respuesta":"Los elementos de protección ayudan, pero solo si se usan bien. La Resolución 2674 de 2013 del Ministerio de Salud y Protección Social lo deja claro en el artículo 14. Guantes (numeral 10) Si se usan, deben estar limpios y sin roturas, y recibir el mismo cuidado que las manos. Usar guantes no reemplaza el lavado de manos. Un guante que tocó dinero, el celular o carne cruda contamina igual que una mano sucia: se cambia. Tapabocas (numeral 6) Se usa tapabocas desechable cuando el riesgo lo exija,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: La lista diligenciada, los incumplimientos que encontraste y cómo los corregiste.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Guantes, tapabocas y comportamientos prohibidos se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Higiene personal y prácticas higiénicas.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente guantes, tapabocas y comportamientos prohibidos en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de guantes, tapabocas y comportamientos prohibidos"}],"keywords":["curso","manipulación","alimentos","guantes","tapabocas","comportamientos","prohibidos","unidad","higiene","personal","prácticas","higiénicas"],"mapa":{"centro":"Guantes, tapabocas y comportamientos prohibidos","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 2. Higiene personal y prácticas higiénicas","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se aplica: Lista de chequeo de prácticas higiénicas","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y anota qué alimento, superficie o práctica está involucrada.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Identifica el peligro y la causa probable.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define la medida de control y la evidencia que debes dejar.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Revisa la fuente y escribe la conclusión.","icono":"FileCheck","evidencia":"Registro del paso"}]},"caso":{"titulo":"Guantes, tapabocas y comportamientos prohibidos","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, el equipo analiza este caso de unidad 2. Higiene personal y prácticas higiénicas: Arma una lista de chequeo con los numerales del artículo 14 de la Resolución 2674 de 2013 y aplícala a ti mismo durante tres turnos. Entregable: La lista diligenciada, los incumplimientos que encontraste y cómo los corregiste. La pregunta que decide esta clase es: Usar guantes:","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Reemplaza el lavado de manos siempre","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"No reemplaza el lavado de manos","correcta":true,"retro":"El numeral 10 aclara que los guantes no reemplazan el lavado de manos."},{"texto":"Es obligatorio en todas las tareas","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"Permite cobrar y servir sin cambiarlos","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."}]}}$j$::jsonb, updated_at = NOW()
   WHERE lesson_id = 1705 AND type = 'experiencia' AND deleted_at IS NULL;
  UPDATE aula_lesson_blocks SET data = $j${"v":1,"duracion":25,"gancho":{"titulo":"Separe crudos y cocinados: la contaminación cruzada","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, la nevera se dañó durante la noche y nadie registró la temperatura. Lo que está en juego es el criterio de separe crudos y cocinados: la contaminación cruzada. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar separe crudos y cocinados: la contaminación cruzada con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar separe crudos y cocinados: la contaminación cruzada con unidad 3. Las cinco claves y el control de temperaturas y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar separe crudos y cocinados: la contaminación cruzada y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"La OMS resume la inocuidad en cinco claves: mantenga la limpieza; separe alimentos crudos y cocinados; cocine completamente; mantenga los alimentos a temperaturas seguras; use agua y materias primas seguras. Esta clase trabaja la segunda. Qué es la contaminación cruzada Es el paso de microorganismos de un alimento crudo, o de sus jugos, a un alimento listo para consumo, directamente o a través de manos, tablas, cuchillos, paños o superficies. La carne roja, las aves y el pescado crudos pueden traer microorganismos peligrosos;…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, separe crudos y cocinados: la contaminación cruzada aparece en medio de una decisión que no admite improvisación: la nevera se dañó durante la noche y nadie registró la temperatura. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Las cinco claves y el control de temperaturas. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: La OMS resume la inocuidad en cinco claves: mantenga la limpieza; separe alimentos crudos y cocinados; cocine completamente; mantenga los alimentos a temperaturas seguras; use agua y materias primas seguras. Esta clase trabaja la segunda. Qué es la contaminación cruzada Es el paso de microorganismos de un alimento crudo, o de sus jugos, a un alimento listo para consumo, directamente o a través de manos, tablas, cuchillos, paños o superficies. La carne roja, las aves y el pescado crudos pueden traer microorganismos peligrosos;…","Una pregunta que se usa para comprobar esta clase es: «¿Qué temperatura interna recomienda la OMS para que un alimento cocinado sea seguro?» La respuesta correcta se apoya en lo siguiente: El manual de la OMS indica que el alimento debe alcanzar 70 °C. La fuente citada es: Resolución 2674 de 2013 y manual de la OMS sobre las cinco claves de la inocuidad.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 3. Las cinco claves y el control de temperaturas y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «El registro, las lecturas fuera de rango y la acción que tomaste en cada caso.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar separe crudos y cocinados: la contaminación cruzada, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y anota qué alimento, superficie o práctica está involucrada. Evidencia que debe quedar: Registro del paso.","Identifica el peligro y la causa probable. Evidencia que debe quedar: Registro del paso.","Define la medida de control y la evidencia que debes dejar. Evidencia que debe quedar: Registro del paso.","Revisa la fuente y escribe la conclusión. Evidencia que debe quedar: Registro del paso.","La respuesta esperada de la unidad ayuda a calibrar el nivel: Aplica la Resolución 2674 de 2013 y las cinco claves de la OMS: separa, cocina, enfría, limpia y usa agua segura. Úsala como espejo, no como texto para copiar: compara tu razonamiento con ella y detecta qué te faltó."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: no documentar la limpieza Corrección: sin registro no se puede demostrar que la limpieza se hizo y se verificó.","Error: lavar la carne cruda en el fregadero Corrección: las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada.","Error: guardar crudos junto a listos para consumo Corrección: la separación evita que los jugos contaminen alimentos que no volverán a cocinarse.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar separe crudos y cocinados: la contaminación cruzada en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Separe crudos y cocinados: la contaminación cruzada»?","respuesta":"La OMS resume la inocuidad en cinco claves: mantenga la limpieza; separe alimentos crudos y cocinados; cocine completamente; mantenga los alimentos a temperaturas seguras; use agua y materias primas seguras. Esta clase trabaja la segunda. Qué es la contaminación cruzada Es el paso de microorganismos de un alimento crudo, o de sus jugos, a un alimento listo para consumo, directamente o a través de manos, tablas, cuchillos, paños o superficies. La carne roja, las aves y el pescado crudos pueden traer microorganismos peligrosos;…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: El registro, las lecturas fuera de rango y la acción que tomaste en cada caso.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Separe crudos y cocinados: la contaminación cruzada se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Las cinco claves y el control de temperaturas.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente separe crudos y cocinados: la contaminación cruzada en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de separe crudos y cocinados: la contaminación cruzada"}],"keywords":["curso","manipulación","alimentos","separe","crudos","cocinados","contaminación","cruzada","unidad","cinco","claves","control"],"mapa":{"centro":"Separe crudos y cocinados: la contaminación cruzada","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 3. Las cinco claves y el control de temperaturas","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se aplica: Registro de temperaturas de una semana","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y anota qué alimento, superficie o práctica está involucrada.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Identifica el peligro y la causa probable.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define la medida de control y la evidencia que debes dejar.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Revisa la fuente y escribe la conclusión.","icono":"FileCheck","evidencia":"Registro del paso"}]},"caso":{"titulo":"Separe crudos y cocinados: la contaminación cruzada","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, el equipo analiza este caso de unidad 3. Las cinco claves y el control de temperaturas: Durante una semana, mide y registra dos veces al día la temperatura de una nevera y de un alimento caliente en exhibición (o de tu casa, si no trabajas en el área). Entregable: El registro, las lecturas fuera de rango y la acción que tomaste en cada caso. La pregunta que decide esta clase es: ¿Qué temperatura interna recomienda la OMS para que un alimento cocinado sea seguro?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"70 °C","correcta":true,"retro":"El manual de la OMS indica que el alimento debe alcanzar 70 °C."},{"texto":"50 °C","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"60 °C","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"40 °C","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."}]}}$j$::jsonb, updated_at = NOW()
   WHERE lesson_id = 1706 AND type = 'experiencia' AND deleted_at IS NULL;
  UPDATE aula_lesson_blocks SET data = $j${"v":1,"duracion":25,"gancho":{"titulo":"Cocine completamente: 70 °C y el recalentado","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, un proveedor entrega un alimento a una temperatura fuera de rango. Lo que está en juego es el criterio de cocine completamente: 70 °C y el recalentado. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar cocine completamente: 70 °C y el recalentado con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar cocine completamente: 70 °C y el recalentado con unidad 3. Las cinco claves y el control de temperaturas y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar cocine completamente: 70 °C y el recalentado y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"La cocción correcta mata casi todos los microorganismos peligrosos. El manual de la OMS indica que los alimentos deben alcanzar 70 °C en su interior y que esa temperatura mata incluso concentraciones altas de microorganismos en 30 segundos. Lo que más hay que vigilar Las carnes rojas, las aves, los huevos y el pescado. En sopas y guisos, hiérvelos para asegurar que alcanzaron los 70 °C. En carnes, los jugos deben salir claros, no rosados; en piezas grandes y en aves, la forma segura de saberlo es el termómetro.…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, cocine completamente: 70 °C y el recalentado aparece en medio de una decisión que no admite improvisación: un proveedor entrega un alimento a una temperatura fuera de rango. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Las cinco claves y el control de temperaturas. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: La cocción correcta mata casi todos los microorganismos peligrosos. El manual de la OMS indica que los alimentos deben alcanzar 70 °C en su interior y que esa temperatura mata incluso concentraciones altas de microorganismos en 30 segundos. Lo que más hay que vigilar Las carnes rojas, las aves, los huevos y el pescado. En sopas y guisos, hiérvelos para asegurar que alcanzaron los 70 °C. En carnes, los jugos deben salir claros, no rosados; en piezas grandes y en aves, la forma segura de saberlo es el termómetro.…","Una pregunta que se usa para comprobar esta clase es: «La zona de peligro va de:» La respuesta correcta se apoya en lo siguiente: Entre 5 y 60 °C los microorganismos se multiplican con gran rapidez. La fuente citada es: Resolución 2674 de 2013 y manual de la OMS sobre las cinco claves de la inocuidad.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 3. Las cinco claves y el control de temperaturas y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «El registro, las lecturas fuera de rango y la acción que tomaste en cada caso.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar cocine completamente: 70 °C y el recalentado, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y anota qué alimento, superficie o práctica está involucrada. Evidencia que debe quedar: Registro del paso.","Identifica el peligro y la causa probable. Evidencia que debe quedar: Registro del paso.","Define la medida de control y la evidencia que debes dejar. Evidencia que debe quedar: Registro del paso.","Revisa la fuente y escribe la conclusión. Evidencia que debe quedar: Registro del paso.","La respuesta esperada de la unidad ayuda a calibrar el nivel: Aplica la Resolución 2674 de 2013 y las cinco claves de la OMS: separa, cocina, enfría, limpia y usa agua segura. Úsala como espejo, no como texto para copiar: compara tu razonamiento con ella y detecta qué te faltó."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: romper la cadena de frío Corrección: una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano.","Error: lavar la carne cruda en el fregadero Corrección: las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada.","Error: no documentar la limpieza Corrección: sin registro no se puede demostrar que la limpieza se hizo y se verificó.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar cocine completamente: 70 °C y el recalentado en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Cocine completamente: 70 °C y el recalentado»?","respuesta":"La cocción correcta mata casi todos los microorganismos peligrosos. El manual de la OMS indica que los alimentos deben alcanzar 70 °C en su interior y que esa temperatura mata incluso concentraciones altas de microorganismos en 30 segundos. Lo que más hay que vigilar Las carnes rojas, las aves, los huevos y el pescado. En sopas y guisos, hiérvelos para asegurar que alcanzaron los 70 °C. En carnes, los jugos deben salir claros, no rosados; en piezas grandes y en aves, la forma segura de saberlo es el termómetro.…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: El registro, las lecturas fuera de rango y la acción que tomaste en cada caso.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Cocine completamente: 70 °C y el recalentado se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Las cinco claves y el control de temperaturas.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente cocine completamente: 70 °C y el recalentado en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de cocine completamente: 70 °C y el recalentado"}],"keywords":["curso","manipulación","alimentos","cocine","completamente","recalentado","unidad","cinco","claves","control","temperaturas"],"mapa":{"centro":"Cocine completamente: 70 °C y el recalentado","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 3. Las cinco claves y el control de temperaturas","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se aplica: Registro de temperaturas de una semana","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y anota qué alimento, superficie o práctica está involucrada.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Identifica el peligro y la causa probable.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define la medida de control y la evidencia que debes dejar.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Revisa la fuente y escribe la conclusión.","icono":"FileCheck","evidencia":"Registro del paso"}]},"caso":{"titulo":"Cocine completamente: 70 °C y el recalentado","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, el equipo analiza este caso de unidad 3. Las cinco claves y el control de temperaturas: Durante una semana, mide y registra dos veces al día la temperatura de una nevera y de un alimento caliente en exhibición (o de tu casa, si no trabajas en el área). Entregable: El registro, las lecturas fuera de rango y la acción que tomaste en cada caso. La pregunta que decide esta clase es: La zona de peligro va de:","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"0 a 20 °C","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"5 a 60 °C","correcta":true,"retro":"Entre 5 y 60 °C los microorganismos se multiplican con gran rapidez."},{"texto":"30 a 90 °C","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."},{"texto":"60 a 100 °C","correcta":false,"retro":"Revisa la explicación de la clase y la fuente citada."}]}}$j$::jsonb, updated_at = NOW()
   WHERE lesson_id = 1707 AND type = 'experiencia' AND deleted_at IS NULL;
  UPDATE aula_lesson_blocks SET data = $j${"v":1,"duracion":25,"gancho":{"titulo":"Temperaturas seguras: la zona de peligro","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, la nevera se dañó durante la noche y nadie registró la temperatura. Lo que está en juego es el criterio de temperaturas seguras: la zona de peligro. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar temperaturas seguras: la zona de peligro con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar temperaturas seguras: la zona de peligro con unidad 3. Las cinco claves y el control de temperaturas y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar temperaturas seguras: la zona de peligro y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Los microorganismos se multiplican con gran rapidez entre 5 °C y 60 °C : la OMS la llama zona de peligro . Por debajo de 5 °C o por encima de 60 °C el crecimiento se frena o se detiene, aunque algunos microorganismos aún crecen por debajo de 5 °C. Las reglas de la OMS No dejes alimentos cocinados a temperatura ambiente más de 2 horas . Refrigera lo antes posible los alimentos cocinados y perecederos, de preferencia por debajo de 5 °C . Mantén la comida caliente a más de 60 °C antes de servirla. No guardes alimentos mucho tiempo,…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, temperaturas seguras: la zona de peligro aparece en medio de una decisión que no admite improvisación: la nevera se dañó durante la noche y nadie registró la temperatura. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Las cinco claves y el control de temperaturas. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Los microorganismos se multiplican con gran rapidez entre 5 °C y 60 °C : la OMS la llama zona de peligro . Por debajo de 5 °C o por encima de 60 °C el crecimiento se frena o se detiene, aunque algunos microorganismos aún crecen por debajo de 5 °C. Las reglas de la OMS No dejes alimentos cocinados a temperatura ambiente más de 2 horas . Refrigera lo antes posible los alimentos cocinados y perecederos, de preferencia por debajo de 5 °C . Mantén la comida caliente a más de 60 °C antes de servirla. No guardes alimentos mucho tiempo,…","Una pregunta que se usa para comprobar esta clase es: «¿Cuánto tiempo, como máximo, puede estar un alimento cocinado a temperatura ambiente?» La respuesta correcta se apoya en lo siguiente: La OMS recomienda no dejarlo más de 2 horas. La fuente citada es: Resolución 2674 de 2013 y manual de la OMS sobre las cinco claves de la inocuidad.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 3. Las cinco claves y el control de temperaturas y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «El registro, las lecturas fuera de rango y la acción que tomaste en cada caso.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar temperaturas seguras: la zona de peligro, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y anota qué alimento, superficie o práctica está involucrada. Evidencia que debe quedar: Registro del paso.","Identifica el peligro y la causa probable. Evidencia que debe quedar: Registro del paso.","Define la medida de control y la evidencia que debes dejar. Evidencia que debe quedar: Registro del paso.","Revisa la fuente y escribe la conclusión. Evidencia que debe quedar: Registro del paso.","La respuesta esperada de la unidad ayuda a calibrar el nivel: Aplica la Resolución 2674 de 2013 y las cinco claves de la OMS: separa, cocina, enfría, limpia y usa agua segura. Úsala como espejo, no como texto para copiar: compara tu razonamiento con ella y detecta qué te faltó."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confiar en el olor o el color Corrección: los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento.","Error: guardar crudos junto a listos para consumo Corrección: la separación evita que los jugos contaminen alimentos que no volverán a cocinarse.","Error: romper la cadena de frío Corrección: una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar temperaturas seguras: la zona de peligro en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Temperaturas seguras: la zona de peligro»?","respuesta":"Los microorganismos se multiplican con gran rapidez entre 5 °C y 60 °C : la OMS la llama zona de peligro . Por debajo de 5 °C o por encima de 60 °C el crecimiento se frena o se detiene, aunque algunos microorganismos aún crecen por debajo de 5 °C. Las reglas de la OMS No dejes alimentos cocinados a temperatura ambiente más de 2 horas . Refrigera lo antes posible los alimentos cocinados y perecederos, de preferencia por debajo de 5 °C . Mantén la comida caliente a más de 60 °C antes de servirla. No guardes alimentos mucho tiempo,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: El registro, las lecturas fuera de rango y la acción que tomaste en cada caso.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Temperaturas seguras: la zona de peligro se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Las cinco claves y el control de temperaturas.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente temperaturas seguras: la zona de peligro en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de temperaturas seguras: la zona de peligro"}],"keywords":["curso","manipulación","alimentos","temperaturas","seguras","peligro","unidad","cinco","claves","control"],"mapa":{"centro":"Temperaturas seguras: la zona de peligro","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","n